import {readFile,mkdir,writeFile} from "node:fs/promises";
import {resolve,join} from "node:path";
import {createHash} from "node:crypto";

const sha = text => createHash("sha256").update(text,"utf8").digest("hex");
const size = text => Buffer.byteLength(text,"utf8");
const opts = {};
for(let i=2;i<process.argv.length;i+=2){
  const key=process.argv[i],value=process.argv[i+1];
  if(!["--source-directory","--generated-directory"].includes(key)||typeof value!=="string"||key in opts)
    throw new Error("Use each complete --source-directory and --generated-directory once");
  opts[key]=value;
}
if(Object.keys(opts).length!==2)throw new Error("Both complete directory arguments are required");
const sourceDirectory=resolve(opts["--source-directory"]);
const generatedDirectory=resolve(opts["--generated-directory"]);
await mkdir(generatedDirectory,{recursive:true});
const produced=[];
for(const recipe of RECIPES){
  let result;
  if("complete_literal_source" in recipe){
    result=recipe.complete_literal_source;
  }else{
    const parent=await readFile(join(sourceDirectory,recipe.parent.name),"utf8");
    if(size(parent)!==recipe.parent.bytes||sha(parent)!==recipe.parent.sha256)
      throw new Error("The entire fixed parent differs: "+recipe.parent.name);
    let previous=parent.length;
    result=parent;
    for(const patch of [...recipe.patches].reverse()){
      if(!Number.isSafeInteger(patch.start)||!Number.isSafeInteger(patch.remove_length)||
         patch.start<0||patch.remove_length<0||patch.start+patch.remove_length>previous)
        throw new Error("Invalid complete nonoverlapping text span");
      const removed=parent.slice(patch.start,patch.start+patch.remove_length);
      if(sha(removed)!==patch.removed_sha256)
        throw new Error("The whole removed source span differs");
      result=result.slice(0,patch.start)+patch.insert+result.slice(patch.start+patch.remove_length);
      previous=patch.start;
    }
    // Exact reversal uses the retained complete parent, never an abbreviated template.
    let reconstructed=result,shift=0;
    const positions=recipe.patches.map(p=>{
      const start=p.start+shift;shift+=p.insert.length-p.remove_length;
      return {...p,result_start:start};
    });
    for(const patch of positions.reverse()){
      if(reconstructed.slice(patch.result_start,patch.result_start+patch.insert.length)!==patch.insert)
        throw new Error("The complete inserted span changed");
      reconstructed=reconstructed.slice(0,patch.result_start)+
        parent.slice(patch.start,patch.start+patch.remove_length)+
        reconstructed.slice(patch.result_start+patch.insert.length);
    }
    if(reconstructed!==parent)throw new Error("Exact full-parent reversal failed");
  }
  if(size(result)!==recipe.output.bytes||sha(result)!==recipe.output.sha256||size(result)>=100000)
    throw new Error("The generated complete source differs: "+recipe.output.name);
  const destination=join(generatedDirectory,recipe.output.name);
  await writeFile(destination,result,"utf8");
  const reread=await readFile(destination,"utf8");
  if(reread!==result)throw new Error("A complete output changed while writing");
  produced.push({...recipe.output,path:destination});
}
process.stdout.write(JSON.stringify({schema:"complete-R726-R727-source-text-reproduction-v1",
  complete:true,complete_original_parents_and_all_output_bytes_verified:true,
  source_modules_imported:false,AST_or_compile_executed:false,
  scientific_arithmetic_or_arrays_or_roots_executed:false,outputs:produced},null,2)+"\n");
